class Employee { String name; double salary; Employee(String name,double salary){this.name=name;this.salary=salary;} void addBonus(double salary){this.salary+=salary;} } public class PayrollBonus { public static void main(String[] a){Employee[] e={new Employee("Ravi",20000),new Employee("Meera",22000)};for(Employee x:e){x.addBonus(1000);System.out.println(x.name+": "+x.salary);}} }
